using UnityEngine;
using UnityEditor;
using System;
using System.Linq;
using ConRoi.Investigation.V36.R103;
using Object = UnityEngine.Object;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            var s = Object.FindFirstObjectByType<InvestigationSession>();
            var g = s.GetComponentsInChildren<InvestigationInteractable>(true).Single(i => i.evidenceId == "shoe");
            foreach (var f in g.GetComponentsInChildren<MeshFilter>())
            {
                var m = f.sharedMesh;
                r.Log(f.name + " transform=" + f.transform.localRotation + " bounds=" + m.bounds);
                for (int j = 0; j < m.subMeshCount; j++)
                {
                    var v = m.GetTriangles(j).Select(k => m.vertices[k]).ToArray();
                    r.Log("sub " + j + " y=" + v.Min(p => p.y) + ".." + v.Max(p => p.y) + " material=" + f.GetComponent<Renderer>().sharedMaterials[j].name);
                }
            }
        }
    }
}

